package com.android.sdk.net.core.result;

import com.android.sdk.net.core.exception.ApiErrorException;

/**
 * Some exceptions generated by business calls are not globally common, you can pass this interface to create specific exceptions.
 */
public interface ApiErrorFactory {

    /**
     * Create specific business exceptions based on {@link Result}.
     */
    ApiErrorException create(Result<?> result, String hostFlag);

}